;;; Data

(def toy-orders
  {:columns ["id" "customer_id" "product_id" "qty"]
   :rows    [[10 1 100 2] [11 1 101 1] [12 3 100 5] [13 4 102 1] [14 9 101 3]]})

(defn lcg [seed]
  (let [state (volatile! (long seed))]
    (fn intn [n]
      (vswap! state #(unchecked-add (unchecked-multiply % 6364136223846793005) 1442695040888963407))
      (mod (unsigned-bit-shift-right @state 33) n))))

(defn generate-orders
  "The 5000 generated orders from DESIGN.md (customers and products are drawn first, so their
  random draws are replayed here to keep the stream identical)."
  []
  (let [intn (lcg 42)]
    (doseq [_ (range 1 201)] (when (>= (intn 100) 72) (intn 5)) (intn 60))   ; customers
    (doseq [_ (range 1 51)] (intn 5) (intn 9900))                           ; products
    {:columns ["id" "customer_id" "product_id" "qty" "day"]
     :rows    (vec (for [id (range 1 5001)]
                     (let [r   (intn 100)
                           cid (if (< r 50) (+ 1 (intn 20)) (+ 1 (intn 200)))
                           pid (+ 1 (intn 50))
                           qty (+ 1 (intn 5))
                           day (+ 1 (intn 365))]
                       [id cid pid qty day])))}))

