;;; Demo

(defn- format-value [v] (cond (nil? v) "NULL" (double? v) (format "%.2f" v) :else (str v)))

(defn print-table [columns rows]
  (let [cells  (cons (vec columns) (map #(mapv format-value %) rows))
        widths (apply map (fn [& col] (apply max (map count col))) cells)
        line   (fn [r] (str/join " | " (map (fn [w c] (format (str "%-" w "s") c)) widths r)))]
    (println (line (first cells)))
    (println (str/join "-+-" (map #(apply str (repeat % "-")) widths)))
    (doseq [r (rest cells)] (println (line r)))))

(defn- header [s] (println) (println (str "== " s " " (apply str (repeat (max 0 (- 70 (count s))) "=")))))

(def ^:private demo-aggs
  [{:fn "count" :arg :* :name "orders"}
   {:fn "sum" :arg [:col "o.qty"] :name "units"}
   {:fn "avg" :arg [:col "o.qty"] :name "avg_qty"}])

(defn -main [& _]
  (header "GROUP BY customer_id — hash aggregate")
  (println "SELECT customer_id, count(*), sum(qty), avg(qty) FROM orders GROUP BY customer_id")
  (println "Input order: customer 1, 1, 3, 4, 9. One accumulator per group, found by hashing the key.")
  (let [op (hash-aggregate (scan toy-orders "o") [[:col "o.customer_id"]] demo-aggs)]
    (print-table (schema op) (run op)))

  (header "Sort aggregate needs sorted input")
  (let [unsorted {:columns (:columns toy-orders) :rows [[10 1 100 2] [12 3 100 5] [11 1 101 1]]}]
    (println "Feed it customer 1, 3, 1 (unsorted) and customer 1 shows up twice:")
    (let [op (sort-aggregate (scan unsorted "o") [[:col "o.customer_id"]] demo-aggs)]
      (print-table (schema op) (run op)))
    (println)
    (println "Sort first, then it streams: one accumulator alive at a time.")
    (let [op (sort-aggregate (sort-op (scan unsorted "o") [[[:col "o.customer_id"] :asc]])
                             [[:col "o.customer_id"]] demo-aggs)]
      (print-table (schema op) (run op))))

  (header "No GROUP BY: one row, even for empty input")
  (let [empty-t {:columns ["id" "customer_id" "product_id" "qty"] :rows []}
        aggs    [{:fn "count" :arg :* :name "count"} {:fn "sum" :arg [:col "o.qty"] :name "sum"}]]
    (print-table ["count" "sum"] (run (hash-aggregate (scan empty-t "o") [] aggs)))
    (println "count of nothing is 0; sum of nothing is NULL."))

  (let [orders (generate-orders)
        keys   [[[:col "o.qty"] :desc] [[:col "o.day"] :asc]]]
    (header "External merge sort: 5000 orders, memory for 500")
    (let [stats (atom {})
          op    (external-sort (scan orders "o") keys 500 {:stats stats})
          rows  (run op)
          ref   (run (sort-op (scan orders "o") keys))]
      (println (format "  %d runs of ≤500 rows, %d heap pops; merged output = in-memory sort? %s"
                       (:runs @stats) (:heap-pops @stats) (= rows ref)))
      (println "  first 3:")
      (print-table (schema op) (take 3 rows)))

    (header "Top-N: ORDER BY qty DESC, day LIMIT 5")
    (let [full-c (atom 0) top-c (atom 0)
          full   (take 5 (run (sort-op (scan orders "o") keys {:counter full-c})))
          top    (run (top-n (scan orders "o") keys 5 {:counter top-c}))]
      (print-table (:columns orders) top)
      (println (format "  full sort then take 5: %,d comparisons" @full-c))
      (println (format "  top-n heap of 5:       %,d comparisons  (same rows? %s)" @top-c (= (vec full) top))))

    (header "Hash vs sort aggregate on 5000 orders")
    (let [aggs [{:fn "count" :arg :* :name "n"} {:fn "sum" :arg [:col "o.qty"] :name "units"}]
          h    (run (hash-aggregate (scan orders "o") [[:col "o.customer_id"]] aggs))
          s    (run (sort-aggregate (sort-op (scan orders "o") [[[:col "o.customer_id"] :asc]])
                                    [[:col "o.customer_id"]] aggs))]
      (println (format "  hash aggregate: %d groups, first-seen order starts %s" (count h) (pr-str (take 3 h))))
      (println (format "  sort aggregate: %d groups, key order starts       %s" (count s) (pr-str (take 3 s))))
      (println (format "  same groups? %s" (= (set h) (set s)))))))
